def apply(inputs, premises):
    if inputs["condition_satisfied"]:
        actual_result = premises["exception_result"]
        contrary_result = premises["default_result"]
    else:
        actual_result = premises["default_result"]
        contrary_result = premises["exception_result"]
    if inputs["claimed_result"] == actual_result:
        answer = "Entailment"
    elif contrary_result != actual_result and inputs["claimed_result"] == contrary_result:
        answer = "Contradiction"
    else:
        answer = "NotMentioned"
    return {"answer": answer}

def apply(inputs, premises):
    dimension_sums = inputs["dimension_sums"]
    weights = inputs["weights"]
    surcharges = []
    for i in range(len(dimension_sums)):
        dimension_sum = int(dimension_sums[i])
        weight = int(weights[i])
        size_fee = 0
        for j in range(len(premises["size_lower_bounds"])):
            lower = int(premises["size_lower_bounds"][j])
            upper = int(premises["size_upper_bounds"][j])
            if dimension_sum > lower and dimension_sum <= upper:
                size_fee = max(size_fee, int(premises["size_fees"][j]))
        weight_fee = 0
        for j in range(len(premises["weight_lower_bounds"])):
            lower = int(premises["weight_lower_bounds"][j])
            upper = int(premises["weight_upper_bounds"][j])
            if weight > lower and weight <= upper:
                weight_fee = max(weight_fee, int(premises["weight_fees"][j]))
        surcharges = surcharges + [max(size_fee, weight_fee)]
    return {"surcharges": surcharges}

